// Formata mensagem executiva para o WhatsApp
const item = items[0].json;
const data = item.data || item;

const statusIcon = data.status_conciliacao === 'CONCILIADO' ? '✅' : '⚠️';
const faturamento = Number(data.faturamento_total || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const litros = Number(data.litros_vendidos || 0).toLocaleString('pt-BR', { minimumFractionDigits: 1 });
const quebra = Number(data.quebra_caixa || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const text = `${statusIcon} *AURA // FECHAMENTO DE TURNO EXECUTIVO*\n` +
  `📅 Data: ${data.data || new Date().toISOString().slice(0,10)} | Turno: ${data.turno_id}\n` +
  `⛽ Filial: ${data.filial_id || 'posto_01'}\n` +
  `----------------------------------------\n` +
  `💰 Faturamento: ${faturamento}\n` +
  `📊 Litros Vendidos: ${litros} L\n` +
  `⚖️ Quebra/Divergência: ${quebra}\n` +
  `🎯 Status: ${data.status_conciliacao || 'CONCILIADO'}\n` +
  `🔌 Bicos Auditados: ${data.bicos_analisados || 0}\n` +
  (data.observacoes ? `\n📝 Obs: ${data.observacoes}` : '');

return [{
  json: {
    number: '{{ $env.WHATSAPP_MANAGER_PHONE }}',
    text: text,
    raw_event: item.event || 'turno_fechamento'
  }
}];
